import itertools
import json

def solve_puzzle():
    # Input variables
    houses = [1, 2]  # House numbers from left to right
    names = ["Eric", "Arnold"]
    birthdays = ["sept", "april"]
    colors = ["yellow", "red"]

    solutions = []

    # Iterate over all possible assignments (permutations) for each attribute
    for name_perm in itertools.permutations(names, len(houses)):
        for birthday_perm in itertools.permutations(birthdays, len(houses)):
            for color_perm in itertools.permutations(colors, len(houses)):
                # Apply constraints

                # Clue 2: The person whose birthday is in April is in the first house.
                if birthday_perm[0] != "april":
                    continue

                # Clue 3: The person who loves yellow is not in the first house.
                if color_perm[0] == "yellow":
                    continue

                # Clue 1: Eric is the person who loves yellow.
                try:
                    idx_eric = name_perm.index("Eric")
                except ValueError:
                    continue
                if color_perm[idx_eric] != "yellow":
                    continue

                # All constraints satisfied; record solution
                solution_rows = []
                for i, h in enumerate(houses):
                    solution_rows.append([str(h), name_perm[i], birthday_perm[i], color_perm[i]])
                solutions.append(solution_rows)

    # Choose the first solution (puzzle is expected to be uniquely solvable)
    if not solutions:
        raise ValueError("No solution found for the given puzzle constraints.")

    chosen = solutions[0]

    result = {
        "solution": {
            "header": ["House", "Name", "Birthday", "Color"],
            "rows": chosen
        }
    }
    return result

if __name__ == "__main__":
    result = solve_puzzle()
    print(json.dumps(result, ensure_ascii=False))
